import AppKit
import Vision
import Foundation

let srcPath = "/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/assets/af2e05b6b5b431e5df9471bd0a60b321-56681394-ab74-4a23-bf0a-8a30dc2cd051.jpg"
let outPath = "/Users/mac/Desktop/常住人口登记卡_曾用名闫凯.jpg"
let previewPath = "/tmp/hukou_with_name_preview.jpg"

guard let srcImg = NSImage(contentsOfFile: srcPath) else { fputs("load fail\n", stderr); exit(1) }
var r = NSRect(origin: .zero, size: srcImg.size)
guard let cgOrig = srcImg.cgImage(forProposedRect: &r, context: nil, hints: nil) else { exit(1) }

// Rotate 90° CW so text is upright for OCR + draw (original is sideways)
func rotate90CW(_ image: CGImage) -> CGImage {
    let w = image.width, h = image.height
    let cs = CGColorSpaceCreateDeviceRGB()
    let ctx = CGContext(data: nil, width: h, height: w, bitsPerComponent: 8, bytesPerRow: 0, space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.translateBy(x: CGFloat(h), y: 0)
    ctx.rotate(by: .pi / 2)
    ctx.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
    return ctx.makeImage()!
}
func rotate90CCW(_ image: CGImage) -> CGImage {
    let w = image.width, h = image.height
    let cs = CGColorSpaceCreateDeviceRGB()
    let ctx = CGContext(data: nil, width: h, height: w, bitsPerComponent: 8, bytesPerRow: 0, space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.translateBy(x: 0, y: CGFloat(w))
    ctx.rotate(by: -.pi / 2)
    ctx.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
    return ctx.makeImage()!
}

let upright = rotate90CW(cgOrig)
let uw = upright.width, uh = upright.height
print("upright \(uw)x\(uh)")

// OCR to find 曾用名 / 闫泽群 boxes (Vision: origin bottom-left, normalized)
let req = VNRecognizeTextRequest()
req.recognitionLevel = .accurate
req.recognitionLanguages = ["zh-Hans", "zh-Hant", "en"]
req.usesLanguageCorrection = false
let handler = VNImageRequestHandler(cgImage: upright, options: [:])
try! handler.perform([req])
var formerLabel: CGRect?
var nameValue: CGRect?
for obs in req.results ?? [] {
    guard let cand = obs.topCandidates(1).first else { continue }
    let t = cand.string.replacingOccurrences(of: " ", with: "")
    let b = obs.boundingBox // normalized, origin bottom-left
    print("OCR '\(cand.string)' box=\(b)")
    if t.contains("曾用名") { formerLabel = b }
    if t.contains("闫泽群") || t.contains("阎泽群") { nameValue = b }
}

guard let fl = formerLabel else {
    fputs("未找到曾用名标签\n", stderr)
    exit(2)
}

// Convert Vision normalized (BL) -> CG pixel (TL origin for drawing in CGContext with flipped?)
// We'll draw in CGContext with default top-left-ish by flipping
func visionToPixels(_ b: CGRect) -> CGRect {
    // Vision: origin bottom-left, normalized
    let x = b.origin.x * CGFloat(uw)
    let yTop = (1 - b.origin.y - b.height) * CGFloat(uh) // top-left y
    let w = b.width * CGFloat(uw)
    let h = b.height * CGFloat(uh)
    return CGRect(x: x, y: yTop, width: w, height: h)
}

let labelPx = visionToPixels(fl)
print("曾用名 label px (TL): \(labelPx)")
if let nv = nameValue {
    print("姓名值 px (TL): \(visionToPixels(nv))")
}

// 曾用名 value cell is to the RIGHT of the label on the same row
// Estimate text position: right of label, vertically centered like 闫泽群
let namePx = nameValue.map(visionToPixels)
let fontSize: CGFloat
if let np = namePx {
    fontSize = max(18, min(np.height * 0.85, 42))
} else {
    fontSize = max(18, labelPx.height * 0.9)
}

let text = "闫凯" as NSString
let font = NSFont(name: "PingFangSC-Medium", size: fontSize)
    ?? NSFont(name: "STSong", size: fontSize)
    ?? NSFont.systemFont(ofSize: fontSize)
let attrs: [NSAttributedString.Key: Any] = [
    .font: font,
    .foregroundColor: NSColor(calibratedWhite: 0.08, alpha: 1.0)
]
let textSize = text.size(withAttributes: attrs)

// Place just to the right of 曾用名 label, same vertical band
let padX: CGFloat = labelPx.width * 0.15
var textX = labelPx.maxX + padX
var textY = labelPx.midY - textSize.height / 2
if let np = namePx {
    // Align X with name value column if possible (曾用名 value under 姓名 value)
    // Prefer slightly right of label; if name is roughly same column, use name's x
    if abs(np.minX - labelPx.maxX) < labelPx.width * 2 {
        textX = np.minX
    }
    textY = labelPx.midY - textSize.height / 2
}
print("draw at (\(textX), \(textY)) font=\(fontSize)")

let cs = CGColorSpaceCreateDeviceRGB()
let ctx = CGContext(data: nil, width: uw, height: uh, bitsPerComponent: 8, bytesPerRow: 0, space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
ctx.draw(upright, in: CGRect(x: 0, y: 0, width: uw, height: uh))
// CGContext y is bottom-left; convert TL y to BL
let drawY = CGFloat(uh) - textY - textSize.height
NSGraphicsContext.saveGraphicsState()
NSGraphicsContext.current = NSGraphicsContext(cgContext: ctx, flipped: false)
text.draw(at: NSPoint(x: textX, y: drawY), withAttributes: attrs)
NSGraphicsContext.restoreGraphicsState()

guard let editedUpright = ctx.makeImage() else { exit(3) }

// Rotate back to original orientation
let editedOrig = rotate90CCW(editedUpright)

func writeJPEG(_ image: CGImage, path: String) {
    let url = URL(fileURLWithPath: path) as CFURL
    let dest = CGImageDestinationCreateWithURL(url, "public.jpeg" as CFString, 1, nil)!
    CGImageDestinationAddImage(dest, image, [kCGImageDestinationLossyCompressionQuality: 0.95] as CFDictionary)
    CGImageDestinationFinalize(dest)
}

writeJPEG(editedOrig, path: outPath)
writeJPEG(editedUpright, path: previewPath)
print("OK -> \(outPath)")
print("preview -> \(previewPath)")
